#!/usr/bin/env node
/** Generates the single module registry from module folders. */

import { readdirSync, readFileSync, writeFileSync } from "node:fs"
import path from "node:path"
import { pathToFileURL } from "node:url"

const root = path.resolve(import.meta.dirname, "..")
const MODULE_KEY = /^[a-z][a-z0-9]*(?:[-_][a-z0-9]+)*$/
// Prettier drops quotes an identifier does not need; matching it here keeps
// the generated file `prettier --check`-clean instead of dirty on every run.
const IDENT = /^[A-Za-z_$][A-Za-z0-9_$]*$/

/** Builds stable TypeScript source for the registered module folders. */
export function generateRegistrySource(moduleKeys) {
  const sortedKeys = [...moduleKeys].sort()
  for (const key of sortedKeys) {
    if (!MODULE_KEY.test(key)) throw new Error(`Invalid module key: ${key}`)
  }
  if (new Set(sortedKeys).size !== sortedKeys.length) throw new Error("Module keys must be unique.")

  const imports = sortedKeys.map((key, index) => `import module_${index} from "./${key}/module"`)
  const entries = sortedKeys.map((key, index) => `  ${IDENT.test(key) ? key : JSON.stringify(key)}: module_${index},`)
  return [
    "/** Generated by scripts/generate-module-registry.mjs. Do not edit. */",
    ...imports,
    "",
    `export const moduleRegistry = {${entries.length > 0 ? `\n${entries.join("\n")}\n` : ""}} as const`,
    "export type ModuleKey = keyof typeof moduleRegistry",
    "",
  ].join("\n")
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  const modulesPath = path.join(root, "src", "modules")
  const registryPath = path.join(modulesPath, "registry.ts")
  const moduleKeys = readdirSync(modulesPath, { withFileTypes: true })
    .filter((entry) => entry.isDirectory() && existsModule(entry.name, modulesPath))
    .map((entry) => entry.name)
  const source = generateRegistrySource(moduleKeys)
  if (readFileSync(registryPath, "utf8") !== source) writeFileSync(registryPath, source)
}

function existsModule(key, modulesPath) {
  try {
    readFileSync(path.join(modulesPath, key, "module.ts"), "utf8")
    return true
  } catch (error) {
    if (error && typeof error === "object" && "code" in error && error.code === "ENOENT") return false
    throw error
  }
}
